import type { Metadata } from "next";
import "./globals.css";
import Sidebar from "@/components/Sidebar";
import AIChatbot from "@/features/chat/components/AIChatbot";
import ToastNotification from "@/components/ToastNotification";
import PageLoader from "@/components/PageLoader";

export const metadata: Metadata = {
  title: "Finter",
  description: "Professional Finance Management Dashboard",
  icons: {
    icon: "/icon.png",
  },
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="id" suppressHydrationWarning>
      <head>
        <script
          dangerouslySetInnerHTML={{
            __html: `
              (function() {
                var isFirstAccess = !sessionStorage.getItem("finter_visited");
                var isReload = false;
                try {
                  var entries = performance.getEntriesByType("navigation");
                  if (entries.length > 0) {
                    isReload = entries[0].type === "reload";
                  } else {
                    isReload = performance.navigation.type === 1;
                  }
                } catch (e) {}

                if (!isFirstAccess && !isReload) {
                  document.documentElement.classList.add("no-loader");
                }
              })();
            `,
          }}
        />
      </head>
      <body className="bg-[#0b1120] min-h-screen antialiased" suppressHydrationWarning>
        <PageLoader />
        <div className="flex h-screen overflow-hidden">
          <Sidebar />
          <main className="flex-1 overflow-y-auto bg-[#0d1526] pt-14 md:pt-0">
            {children}
          </main>
        </div>
        <AIChatbot />
        <ToastNotification />
      </body>
    </html>
  );
}